formula:
=LET(
  col_medio; Registros!F7:F;
  col_cuenta; Registros!D7:D;
  col_fecha; Registros!H7:H;
  col_moneda; Registros!G7:G;
  neto; ARRAYFORMULA(IF(Registros!C7:C="Egreso"; -Registros!B7:B; Registros!B7:B));
  lista; IFERROR(FILTER('Plan de Cuentas'!L8:L; 'Plan de Cuentas'!L8:L<>""); "");
  cortes; MAP(lista; LAMBDA(un_medio; MAX(IFERROR(FILTER(col_fecha; col_medio=un_medio; col_cuenta="Inicio Mes"); 0))));
  corte_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; HSTACK(lista; cortes); 2; 0); ""));
  vigente; ARRAYFORMULA((corte_fila<>"") * (col_fecha>=corte_fila));
  tipo_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; 'Plan de Cuentas'!L:N; 3; 0); ""));
  mon_lista; ARRAYFORMULA(IFERROR(VLOOKUP(lista; 'Plan de Cuentas'!L:N; 2; 0); "ARS"));
  grupo; ARRAYFORMULA((tipo_fila<>"Ahorros") * (tipo_fila<>"Inversiones") > 0);
  suma_ars; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="ARS"); 0));
  suma_usd; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="USD"); 0));
  suma_aud; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="AUD"); 0));
  suma_eur; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="EUR"); 0));
  total_ars; suma_ars + (suma_usd * TIDETRACK_USD()) + (suma_aud * TIDETRACK_AUD()) + (suma_eur * TIDETRACK_EUR());
  tasa_destino; IFERROR(SWITCH($I$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
  total_ars / tasa_destino
)

=LET(
  col_medio; Registros!F7:F;
  col_cuenta; Registros!D7:D;
  col_fecha; Registros!H7:H;
  col_moneda; Registros!G7:G;
  neto; ARRAYFORMULA(IF(Registros!C7:C="Egreso"; -Registros!B7:B; Registros!B7:B));
  lista; IFERROR(FILTER('Plan de Cuentas'!L8:L; 'Plan de Cuentas'!L8:L<>""); "");
  cortes; MAP(lista; LAMBDA(un_medio; MAX(IFERROR(FILTER(col_fecha; col_medio=un_medio; col_cuenta="Inicio Mes"); 0))));
  corte_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; HSTACK(lista; cortes); 2; 0); ""));
  vigente; ARRAYFORMULA((corte_fila<>"") * (col_fecha>=corte_fila));
  tipo_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; 'Plan de Cuentas'!L:N; 3; 0); ""));
  mon_lista; ARRAYFORMULA(IFERROR(VLOOKUP(lista; 'Plan de Cuentas'!L:N; 2; 0); "ARS"));
  grupo; ARRAYFORMULA(((tipo_fila="Ahorros") + (tipo_fila="Inversiones")) > 0);
  suma_ars; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="ARS"); 0));
  suma_usd; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="USD"); 0));
  suma_aud; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="AUD"); 0));
  suma_eur; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="EUR"); 0));
  total_ars; suma_ars + (suma_usd * TIDETRACK_USD()) + (suma_aud * TIDETRACK_AUD()) + (suma_eur * TIDETRACK_EUR());
  tasa_destino; IFERROR(SWITCH($I$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
  total_ars / tasa_destino
)

=LET(
  mes_num; MATCH(I2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(I3; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(I3; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!B6:M;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(T8:T=""; "";
    LET(
      tasa_origen; IF(Y8:Y="ARS"; AB8:AB; IF(Y8:Y="USD"; AC8:AC; IF(Y8:Y="AUD"; AD8:AD; IF(Y8:Y="EUR"; AE8:AE; 1))));
      tasa_destino; IF(I4="ARS"; AB8:AB; IF(I4="USD"; AC8:AC; IF(I4="AUD"; AD8:AD; IF(I4="EUR"; AE8:AE; 1))));
      IFERROR((T8:T * tasa_origen) / tasa_destino; 0)
    )
  )
)

=LET(
  mes_num; MATCH(I2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(I3; mes_num - 1; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(I3; mes_num - 1; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!B6:M;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(AH8:AH=""; "";
    LET(
      tasa_origen; IF(AM8:AM="ARS"; AP8:AP; IF(AM8:AM="USD"; AQ8:AQ; IF(AM8:AM="AUD"; AR8:AR; IF(AM8:AM="EUR"; AS8:AS; 1))));
      tasa_destino; IF($I$4="ARS"; AP8:AP; IF($I$4="USD"; AQ8:AQ; IF($I$4="AUD"; AR8:AR; IF($I$4="EUR"; AS8:AS; 1))));
      IFERROR((AH8:AH * tasa_origen) / tasa_destino; 0)
    )
  )
)

=IFERROR(QUERY(
  ARRAYFORMULA({
    V8:V \ 
    IF(U8:U="Egreso"; -AF8:AF; AF8:AF) \ 
    W8:W \ 
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "") \
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "")
  });
  "SELECT SUM(Col2) 
   WHERE Col3 = 'Ingreso' 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND Col1 != 'Inicio Mes' 
   LABEL SUM(Col2) ''";
  0
); 0)

=IFERROR(QUERY(
  ARRAYFORMULA({
    V8:V \ 
    IF(U8:U="Ingreso"; -AF8:AF; AF8:AF) \ 
    W8:W \ 
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "") \
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "")
  });
  "SELECT SUM(Col2) 
   WHERE (Col3 = 'Gasto Fijo' OR Col3 = 'Gasto Variable') 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND Col1 != 'Inicio Mes' 
   LABEL SUM(Col2) ''";
  0
); 0)

=LET(
  monto_act; AF8:AF; tipo_act; U8:U; cuenta_act; V8:V; cat_act; W8:W; medio_act; X8:X;
  monto_ant; AT8:AT; tipo_ant; AI8:AI; cuenta_ant; AJ8:AJ; cat_ant; AK8:AK; medio_ant; AL8:AL;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Egreso"; -monto_act; monto_act));
  monto_neto_ant; ARRAYFORMULA(IF(tipo_ant="Egreso"; -monto_ant; monto_ant));

  proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(medio_act; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_act; proy_act;

  proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(medio_ant; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_ant; proy_ant;

  cond_ingreso_act; cat_act = "Ingreso";
  cond_no_traspaso_act; cuenta_act <> "Traspaso";
  cond_inicio_act; ARRAYFORMULA(cuenta_act <> "Inicio Mes");

  cond_ingreso_ant; cat_ant = "Ingreso";
  cond_no_traspaso_ant; cuenta_ant <> "Traspaso";
  cond_inicio_ant; ARRAYFORMULA(cuenta_ant <> "Inicio Mes");

  ingreso_act_ars; SUM(IFERROR(FILTER(monto_neto_act; cond_ingreso_act; cond_no_traspaso_act; cond_inicio_act); 0));
  ingreso_ant_ars; SUM(IFERROR(FILTER(monto_neto_ant; cond_ingreso_ant; cond_no_traspaso_ant; cond_inicio_ant); 0));

  variacion; IF(ingreso_ant_ars = 0; IF(ingreso_act_ars > 0; 1; 0); (ingreso_act_ars - ingreso_ant_ars) / ingreso_ant_ars);

  TEXT(variacion; "+0,0%;-0,0%;0%") & " respecto del mes anterior."
)

=LET(
  monto_act; AF8:AF; tipo_act; U8:U; cuenta_act; V8:V; cat_act; W8:W; medio_act; X8:X;
  monto_ant; AT8:AT; tipo_ant; AI8:AI; cuenta_ant; AJ8:AJ; cat_ant; AK8:AK; medio_ant; AL8:AL;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Ingreso"; -monto_act; monto_act));
