  mon; IFERROR(FILTER(moneda; valido); "");
  imp; IFERROR(FILTER(neto; valido); 0);
  IFERROR(QUERY(ARRAYFORMULA(HSTACK(med; mon; imp));
    "SELECT Col1, Col2, SUM(Col3) WHERE Col1 IS NOT NULL AND Col1 <> '' GROUP BY Col1, Col2 ORDER BY SUM(Col3) DESC LABEL Col1 '', Col2 '', SUM(Col3) ''"; 0);
    HSTACK(""; ""; ""))
)

=LET(
  liquidez_ars; AF9 + (AF10 * $AF$17) + (AF11 * $AF$18) + (AF12 * $AF$19);
  tasa_cambio; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$17; "AUD"; $AF$18; "EUR"; $AF$19); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  presupuesto_ahorro; $N$9 - $N$10 - $N$11;
  real_ahorro; $N$19;

  rem_ahorro; MAX(0; presupuesto_ahorro - real_ahorro);
  rem_fijos; MAX(0; $N$10 - $N$17);
  rem_var; MAX(0; $N$11 - $N$18);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; MIN(rem_fijos; liquidez_moneda * (rem_fijos / suma_rem)); 0)
)

=LET(
  liquidez_ars; AF9 + (AF10 * $AF$17) + (AF11 * $AF$18) + (AF12 * $AF$19);
  tasa_cambio; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$17; "AUD"; $AF$18; "EUR"; $AF$19); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  presupuesto_ahorro; $N$9 - $N$10 - $N$11;
  real_ahorro; $N$19;

  rem_ahorro; MAX(0; presupuesto_ahorro - real_ahorro);
  rem_fijos; MAX(0; $N$10 - $N$17);
  rem_var; MAX(0; $N$11 - $N$18);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; MIN(rem_var; liquidez_moneda * (rem_var / suma_rem)); 0)
)

=LET(
  liquidez_ars; AF9 + (AF10 * $AF$17) + (AF11 * $AF$18) + (AF12 * $AF$19);
  tasa_cambio; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$17; "AUD"; $AF$18; "EUR"; $AF$19); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  presupuesto_ahorro; $N$9 - $N$10 - $N$11;
  real_ahorro; $N$19;

  rem_ahorro; MAX(0; presupuesto_ahorro - real_ahorro);
  rem_fijos; MAX(0; $N$10 - $N$17);
  rem_var; MAX(0; $N$11 - $N$18);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  base_ahorro; IF(suma_rem > 0; MIN(rem_ahorro; liquidez_moneda * (rem_ahorro / suma_rem)); 0);
  excedente; IF(liquidez_moneda > suma_rem; liquidez_moneda - suma_rem; 0);

  IF(suma_rem = 0; liquidez_moneda; base_ahorro + excedente)
)

=LET(
  ingresos_traspaso; SUMIFS(AV6:AV; AL6:AL; "Traspaso"; AK6:AK; "Ingreso");
  egresos_traspaso; SUMIFS(AV6:AV; AL6:AL; "Traspaso"; AK6:AK; "Egreso");
  diferencia; ROUND(ingresos_traspaso - egresos_traspaso; 2);

  IF(diferencia = 0;
    "Traspasos balanceados";
    "Descuadre en Traspasos por " & TEXT(diferencia; "$ #.##0,00")
  )
)

formula:
=LET(
  mes_num; MATCH(N2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(N3; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(N3; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!B6:M;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(AJ6:AJ=""; "";
    LET(
      tasa_origen; IF(AO6:AO="ARS"; AR6:AR; IF(AO6:AO="USD"; AS6:AS; IF(AO6:AO="AUD"; AT6:AT; IF(AO6:AO="EUR"; AU6:AU; 1))));
      tasa_destino; IF($N$4="ARS"; AR6:AR; IF($N$4="USD"; AS6:AS; IF($N$4="AUD"; AT6:AT; IF($N$4="EUR"; AU6:AU; 1))));
      IFERROR((AJ6:AJ * tasa_origen) / tasa_destino; 0)
    )
  )
)

=LET(
  monto; Proyeccion!B7:B;
  cuenta; Proyeccion!D7:D;
  tipo_cuenta; Proyeccion!E7:E;
  moneda; Proyeccion!G7:G;
  fecha; Proyeccion!H7:H;
  mes_num; MATCH($N$2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  desde; DATE($N$3; mes_num; 1);
  hasta; EOMONTH(desde; 0);
  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; TIDETRACK_USD(); IF(moneda="AUD"; TIDETRACK_AUD(); IF(moneda="EUR"; TIDETRACK_EUR(); 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
  convertido; ARRAYFORMULA(monto * tasa_origen / tasa_destino);
  del_mes; ARRAYFORMULA((tipo_cuenta="Ingreso") * (cuenta<>"Traspaso") * (cuenta<>"Inicio Mes") * (fecha>=desde) * (fecha<=hasta));
  SUM(IFERROR(FILTER(convertido; del_mes); 0))
)

=LET(
  medio; AN6:AN;
  moneda; AO6:AO;

  monto_neto; ARRAYFORMULA(IF(AJ6:AJ=""; 0; IF(AK6:AK="Egreso"; -AJ6:AJ; AJ6:AJ)));

  proyecto; ARRAYFORMULA(IFERROR(VLOOKUP(AL6:AL; 'Plan de Cuentas'!C:D; 2; 0); IFERROR(VLOOKUP(AL6:AL; 'Plan de Cuentas'!F:G; 2; 0); IFERROR(VLOOKUP(AL6:AL; 'Plan de Cuentas'!I:J; 2; 0); ""))));
  tipo_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyecto; 'Plan de Cuentas'!P:P; 2; 0); ""));

  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AF$27; IF(moneda="AUD"; $AF$28; IF(moneda="EUR"; $AF$29; 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$27; "AUD"; $AF$28; "EUR"; $AF$29); 1);

  monto_convertido; ARRAYFORMULA(IFERROR((monto_neto * tasa_origen) / tasa_destino; 0));

  condicion; ARRAYFORMULA(proyecto<>"");

  proy_filtrado; FILTER(proyecto; condicion);
  monto_filtrado; FILTER(monto_convertido; condicion);

  resultado_query; IFERROR(QUERY(
    {proy_filtrado \ monto_filtrado};
    "SELECT Col1, SUM(Col2) 
     GROUP BY Col1 
     ORDER BY SUM(Col2) DESC 
     LABEL Col1 '', SUM(Col2) ''";
    0
  ); {"" \ ""});

  columna_aj; INDEX(resultado_query; 0; 1);
  columna_al; INDEX(resultado_query; 0; 2);
  columna_tipo; ARRAYFORMULA(IFERROR(VLOOKUP(columna_aj; 'Plan de Cuentas'!P:P; 2; 0); ""));

  {columna_aj \ columna_tipo \ columna_al}
)

=LET(
  col_medio; Registros!F7:F;
  col_cuenta; Registros!D7:D;
  col_fecha; Registros!H7:H;
  col_moneda; Registros!G7:G;
  neto; ARRAYFORMULA(IF(Registros!C7:C="Egreso"; -Registros!B7:B; Registros!B7:B));
  lista; IFERROR(FILTER('Plan de Cuentas'!L8:L; 'Plan de Cuentas'!L8:L<>""); "");
  cortes; MAP(lista; LAMBDA(un_medio; MAX(IFERROR(FILTER(col_fecha; col_medio=un_medio; col_cuenta="Inicio Mes"); 0))));
  corte_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; HSTACK(lista; cortes); 2; 0); ""));
  vigente; ARRAYFORMULA((corte_fila<>"") * (col_fecha>=corte_fila));
  tipo_fila; ARRAYFORMULA(IFERROR(VLOOKUP(col_medio; 'Plan de Cuentas'!L:N; 3; 0); ""));
  mon_lista; ARRAYFORMULA(IFERROR(VLOOKUP(lista; 'Plan de Cuentas'!L:N; 2; 0); "ARS"));
  grupo; ARRAYFORMULA(tipo_fila=AE9);
  suma_ars; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="ARS"); 0));
  suma_usd; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="USD"); 0));
  suma_aud; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="AUD"); 0));
  suma_eur; SUM(IFERROR(FILTER(neto; vigente; grupo; col_moneda="EUR"); 0));
  total_ars; suma_ars + (suma_usd * TIDETRACK_USD()) + (suma_aud * TIDETRACK_AUD()) + (suma_eur * TIDETRACK_EUR());
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
  total_ars / tasa_destino
)

