  parte_sin_presupuesto; IF(suma_peso > 0; peso_capitalizacion / suma_peso; 1/3);
  reparto; IF(suma_rem > 0; MIN(rem_capitalizacion; liquidez * rem_capitalizacion / suma_rem); liquidez * parte_sin_presupuesto);
  excedente; IF(suma_rem > 0; MAX(0; liquidez - suma_rem); 0);
  reparto + excedente
)

=LET(
  ingresos_traspaso; SUMIFS(AV6:AV; AL6:AL; "Traspaso"; AK6:AK; "Ingreso");
  egresos_traspaso; SUMIFS(AV6:AV; AL6:AL; "Traspaso"; AK6:AK; "Egreso");
  diferencia; ROUND(ingresos_traspaso - egresos_traspaso; 2);

  IF(diferencia = 0;
    "Traspasos balanceados";
    "Descuadre en Traspasos por " & TEXT(diferencia; "$ #.##0,00")
  )
)

=LET(
