  reparto; IF(suma_rem > 0; MIN(rem_variables; liquidez * rem_variables / suma_rem); liquidez * parte_sin_presupuesto);
  reparto
)

=LET(
  liquidez_ars; $AF$18 + ($AF$19 * TIDETRACK_USD()) + ($AF$20 * TIDETRACK_AUD()) + ($AF$21 * TIDETRACK_EUR());
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
