  reparto; IF(suma_rem > 0; MIN(rem_capitalizacion; liquidez * rem_capitalizacion / suma_rem); liquidez * parte_sin_presupuesto);
  excedente; IF(suma_rem > 0; MAX(0; liquidez - suma_rem); 0);
  reparto + excedente
)

