=LET(
  liquidez_ars; $AF$18 + ($AF$19 * TIDETRACK_USD()) + ($AF$20 * TIDETRACK_AUD()) + ($AF$21 * TIDETRACK_EUR());
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; TIDETRACK_USD(); "AUD"; TIDETRACK_AUD(); "EUR"; TIDETRACK_EUR()); 1);
  liquidez; liquidez_ars / tasa_destino;
  rem_fijos; MAX(0; $N$10 - $N$17);
  rem_variables; MAX(0; $N$11 - $N$18);
  rem_capitalizacion; MAX(0; $N$12 - $N$19);
  suma_rem; rem_fijos + rem_variables + rem_capitalizacion;
  peso_fijos; MAX(0; $N$10);
  peso_variables; MAX(0; $N$11);
  peso_capitalizacion; MAX(0; $N$12);
  suma_peso; peso_fijos + peso_variables + peso_capitalizacion;
  parte_sin_presupuesto; IF(suma_peso > 0; peso_fijos / suma_peso; 1/3);
  reparto; IF(suma_rem > 0; MIN(rem_fijos; liquidez * rem_fijos / suma_rem); liquidez * parte_sin_presupuesto);
  reparto
)

