  columna_al; INDEX(resultado_query; 0; 2);
  columna_tipo; ARRAYFORMULA(IFERROR(VLOOKUP(columna_aj; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  {columna_aj \ columna_tipo \ columna_al}
)

