  suma_eur; SUM(IFERROR(FILTER(monto_neto; AO6:AO="EUR"; cond_inicio; cond_ahorro); 0));

  total_ars; suma_ars + (suma_usd * $AF$17) + (suma_aud * $AF$18) + (suma_eur * $AF$19);

  tasa_cambio; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$17; "AUD"; $AF$18; "EUR"; $AF$19); 1);

  total_ars / tasa_cambio
