=LET(
  liquidez_ars; AF9 + (AF10 * $AF$17) + (AF11 * $AF$18) + (AF12 * $AF$19);
  tasa_cambio; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$17; "AUD"; $AF$18; "EUR"; $AF$19); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  presupuesto_ahorro; $N$9 - $N$10 - $N$11;
  real_ahorro; $N$19;

  rem_ahorro; MAX(0; presupuesto_ahorro - real_ahorro);
  rem_fijos; MAX(0; $N$10 - $N$17);
  rem_var; MAX(0; $N$11 - $N$18);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; MIN(rem_fijos; liquidez_moneda * (rem_fijos / suma_rem)); 0)
)

