=ARRAYFORMULA(
  IF(AH8:AH=""; "";
    LET(
      tasa_origen; IF(AM8:AM="ARS"; AP8:AP; IF(AM8:AM="USD"; AQ8:AQ; IF(AM8:AM="AUD"; AR8:AR; IF(AM8:AM="EUR"; AS8:AS; 1))));
      tasa_destino; IF($G$4="ARS"; AP8:AP; IF($G$4="USD"; AQ8:AQ; IF($G$4="AUD"; AR8:AR; IF($G$4="EUR"; AS8:AS; 1))));
      IFERROR((AH8:AH * tasa_origen) / tasa_destino; 0)
    )
  )
