=LET(
  monto; Proyeccion!B7:B;
  cuenta; Proyeccion!D7:D;
  tipo_cuenta; Proyeccion!E7:E;
  moneda; Proyeccion!G7:G;
  fecha; Proyeccion!H7:H;
  mes_num; MATCH($N$2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  desde; DATE($N$3; mes_num; 1);
  hasta; EOMONTH(desde; 0);
  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AF$27; IF(moneda="AUD"; $AF$28; IF(moneda="EUR"; $AF$29; 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$27; "AUD"; $AF$28; "EUR"; $AF$29); 1);
  convertido; ARRAYFORMULA(monto * tasa_origen / tasa_destino);
  del_mes; ARRAYFORMULA((tipo_cuenta="Ingreso") * (cuenta<>"Traspaso") * (cuenta<>"Inicio Mes") * (fecha>=desde) * (fecha<=hasta));
  SUM(IFERROR(FILTER(convertido; del_mes); 0))
)

=LET(
  medio; AN6:AN;
  moneda; AO6:AO;

  monto_neto; ARRAYFORMULA(IF(AJ6:AJ=""; 0; IF(AK6:AK="Egreso"; -AJ6:AJ; AJ6:AJ)));

  proyecto; ARRAYFORMULA(IFERROR(VLOOKUP(medio; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyecto; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AF$27; IF(moneda="AUD"; $AF$28; IF(moneda="EUR"; $AF$29; 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$27; "AUD"; $AF$28; "EUR"; $AF$29); 1);

  monto_convertido; ARRAYFORMULA(IFERROR((monto_neto * tasa_origen) / tasa_destino; 0));

  condicion; ARRAYFORMULA(proyecto<>"");

  proy_filtrado; FILTER(proyecto; condicion);
  monto_filtrado; FILTER(monto_convertido; condicion);

  resultado_query; IFERROR(QUERY(
    {proy_filtrado \ monto_filtrado};
    "SELECT Col1, SUM(Col2) 
     GROUP BY Col1 
     ORDER BY SUM(Col2) DESC 
     LABEL Col1 '', SUM(Col2) ''";
    0
  ); {"" \ ""});

  columna_aj; INDEX(resultado_query; 0; 1);
  columna_al; INDEX(resultado_query; 0; 2);
  columna_tipo; ARRAYFORMULA(IFERROR(VLOOKUP(columna_aj; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  {columna_aj \ columna_tipo \ columna_al}
)

