  IF(T8:T=""; "";
    LET(
      tasa_origen; IF(Y8:Y="ARS"; AB8:AB; IF(Y8:Y="USD"; AC8:AC; IF(Y8:Y="AUD"; AD8:AD; IF(Y8:Y="EUR"; AE8:AE; 1))));
      tasa_destino; IF(G4="ARS"; AB8:AB; IF(G4="USD"; AC8:AC; IF(G4="AUD"; AD8:AD; IF(G4="EUR"; AE8:AE; 1))));
      IFERROR((T8:T * tasa_origen) / tasa_destino; 0)
    )
  )
)

