=IFERROR(QUERY(
  ARRAYFORMULA({
    V8:V \ 
    IF(U8:U="Egreso"; -AF8:AF; AF8:AF) \ 
    W8:W \ 
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "") \
    IFERROR(VLOOKUP(IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); ""); 'Plan de Cuentas'!P:Q; 2; 0); "")
  });
  "SELECT SUM(Col2) 
   WHERE Col3 = 'Ingreso' 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND Col1 != 'Inicio Mes' 
   LABEL SUM(Col2) ''";
  0
); 0)

=IFERROR(QUERY(
  ARRAYFORMULA({
    V8:V \ 
    IF(U8:U="Ingreso"; -AF8:AF; AF8:AF) \ 
    W8:W \ 
    IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); "") \
    IFERROR(VLOOKUP(IFERROR(VLOOKUP(X8:X; 'Plan de Cuentas'!L:N; 3; 0); ""); 'Plan de Cuentas'!P:Q; 2; 0); "")
  });
  "SELECT SUM(Col2) 
   WHERE (Col3 = 'Gasto Fijo' OR Col3 = 'Gasto Variable') 
   AND Col1 != 'Traspaso' 
   AND Col1 IS NOT NULL 
   AND Col1 != 'Inicio Mes' 
   LABEL SUM(Col2) ''";
  0
); 0)

=LET(
  monto_act; AF8:AF; tipo_act; U8:U; cuenta_act; V8:V; cat_act; W8:W; medio_act; X8:X;
  monto_ant; AT8:AT; tipo_ant; AI8:AI; cuenta_ant; AJ8:AJ; cat_ant; AK8:AK; medio_ant; AL8:AL;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Egreso"; -monto_act; monto_act));
  monto_neto_ant; ARRAYFORMULA(IF(tipo_ant="Egreso"; -monto_ant; monto_ant));

  proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(medio_act; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(proy_act; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(medio_ant; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(proy_ant; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  cond_ingreso_act; cat_act = "Ingreso";
  cond_no_traspaso_act; cuenta_act <> "Traspaso";
  cond_inicio_act; ARRAYFORMULA(cuenta_act <> "Inicio Mes");

  cond_ingreso_ant; cat_ant = "Ingreso";
  cond_no_traspaso_ant; cuenta_ant <> "Traspaso";
  cond_inicio_ant; ARRAYFORMULA(cuenta_ant <> "Inicio Mes");

  ingreso_act_ars; SUM(IFERROR(FILTER(monto_neto_act; cond_ingreso_act; cond_no_traspaso_act; cond_inicio_act); 0));
  ingreso_ant_ars; SUM(IFERROR(FILTER(monto_neto_ant; cond_ingreso_ant; cond_no_traspaso_ant; cond_inicio_ant); 0));

  variacion; IF(ingreso_ant_ars = 0; IF(ingreso_act_ars > 0; 1; 0); (ingreso_act_ars - ingreso_ant_ars) / ingreso_ant_ars);

  TEXT(variacion; "+0,0%;-0,0%;0%") & " respecto del mes anterior."
)

=LET(
  monto_act; AF8:AF; tipo_act; U8:U; cuenta_act; V8:V; cat_act; W8:W; medio_act; X8:X;
  monto_ant; AT8:AT; tipo_ant; AI8:AI; cuenta_ant; AJ8:AJ; cat_ant; AK8:AK; medio_ant; AL8:AL;

  monto_neto_act; ARRAYFORMULA(IF(tipo_act="Ingreso"; -monto_act; monto_act));
  monto_neto_ant; ARRAYFORMULA(IF(tipo_ant="Ingreso"; -monto_ant; monto_ant));

  proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(medio_act; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_act; ARRAYFORMULA(IFERROR(VLOOKUP(proy_act; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(medio_ant; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy_ant; ARRAYFORMULA(IFERROR(VLOOKUP(proy_ant; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  cond_egreso_act; ARRAYFORMULA((cat_act = "Gasto Fijo") + (cat_act = "Gasto Variable") > 0);
  cond_no_traspaso_act; cuenta_act <> "Traspaso";
  cond_inicio_act; ARRAYFORMULA(cuenta_act <> "Inicio Mes");

  cond_egreso_ant; ARRAYFORMULA((cat_ant = "Gasto Fijo") + (cat_ant = "Gasto Variable") > 0);
  cond_no_traspaso_ant; cuenta_ant <> "Traspaso";
  cond_inicio_ant; ARRAYFORMULA(cuenta_ant <> "Inicio Mes");

  egreso_act_ars; SUM(IFERROR(FILTER(monto_neto_act; cond_egreso_act; cond_no_traspaso_act; cond_inicio_act); 0));
  egreso_ant_ars; SUM(IFERROR(FILTER(monto_neto_ant; cond_egreso_ant; cond_no_traspaso_ant; cond_inicio_ant); 0));

  variacion; IF(egreso_ant_ars = 0; IF(egreso_act_ars > 0; 1; 0); (egreso_act_ars - egreso_ant_ars) / egreso_ant_ars);

  TEXT(variacion; "+0,0%;-0,0%;0%") & " respecto del mes anterior."
)

=LET(
  mes_num; MATCH(N2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(N3; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(N3; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!B6:M;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(AJ6:AJ=""; "";
    LET(
      tasa_origen; IF(AO6:AO="ARS"; AR6:AR; IF(AO6:AO="USD"; AS6:AS; IF(AO6:AO="AUD"; AT6:AT; IF(AO6:AO="EUR"; AU6:AU; 1))));
      tasa_destino; IF($N$4="ARS"; AR6:AR; IF($N$4="USD"; AS6:AS; IF($N$4="AUD"; AT6:AT; IF($N$4="EUR"; AU6:AU; 1))));
      IFERROR((AJ6:AJ * tasa_origen) / tasa_destino; 0)
    )
  )
)

=LET(
  monto; Proyeccion!B7:B;
  cuenta; Proyeccion!D7:D;
  tipo_cuenta; Proyeccion!E7:E;
  moneda; Proyeccion!G7:G;
  fecha; Proyeccion!H7:H;
  mes_num; MATCH($N$2; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  desde; DATE($N$3; mes_num; 1);
  hasta; EOMONTH(desde; 0);
  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AF$27; IF(moneda="AUD"; $AF$28; IF(moneda="EUR"; $AF$29; 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$27; "AUD"; $AF$28; "EUR"; $AF$29); 1);
  convertido; ARRAYFORMULA(monto * tasa_origen / tasa_destino);
  del_mes; ARRAYFORMULA((tipo_cuenta="Ingreso") * (cuenta<>"Traspaso") * (cuenta<>"Inicio Mes") * (fecha>=desde) * (fecha<=hasta));
  SUM(IFERROR(FILTER(convertido; del_mes); 0))
)

=LET(
  medio; AN6:AN;
  moneda; AO6:AO;

  monto_neto; ARRAYFORMULA(IF(AJ6:AJ=""; 0; IF(AK6:AK="Egreso"; -AJ6:AJ; AJ6:AJ)));

  proyecto; ARRAYFORMULA(IFERROR(VLOOKUP(medio; 'Plan de Cuentas'!L:N; 3; 0); ""));
  tipo_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyecto; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AF$27; IF(moneda="AUD"; $AF$28; IF(moneda="EUR"; $AF$29; 1))));
  tasa_destino; IFERROR(SWITCH($N$4; "ARS"; 1; "USD"; $AF$27; "AUD"; $AF$28; "EUR"; $AF$29); 1);

  monto_convertido; ARRAYFORMULA(IFERROR((monto_neto * tasa_origen) / tasa_destino; 0));

  condicion; ARRAYFORMULA(proyecto<>"");

  proy_filtrado; FILTER(proyecto; condicion);
  monto_filtrado; FILTER(monto_convertido; condicion);

  resultado_query; IFERROR(QUERY(
    {proy_filtrado \ monto_filtrado};
    "SELECT Col1, SUM(Col2) 
     GROUP BY Col1 
     ORDER BY SUM(Col2) DESC 
     LABEL Col1 '', SUM(Col2) ''";
    0
  ); {"" \ ""});

  columna_aj; INDEX(resultado_query; 0; 1);
  columna_al; INDEX(resultado_query; 0; 2);
  columna_tipo; ARRAYFORMULA(IFERROR(VLOOKUP(columna_aj; 'Plan de Cuentas'!P:Q; 2; 0); ""));

  {columna_aj \ columna_tipo \ columna_al}
)

